/* Only the hooks are exported: nothing else of the library (Rust's std, the unwinder) can
   interpose a symbol of the program it is loaded into. */
{
  global:
    open; open64; openat; openat64; creat; access; eaccess; euidaccess; faccessat;
    __open_2; __open64_2; __openat_2; __openat64_2;
    stat; stat64; lstat; lstat64; fstatat; fstatat64; statx;
    __xstat; __xstat64; __lxstat; __lxstat64; __fxstatat; __fxstatat64;
    statfs; statfs64; statvfs; statvfs64;
    fopen; fopen64; freopen; freopen64; opendir; scandir; readlink; readlinkat;
    realpath; canonicalize_file_name; chdir; dlopen; inotify_add_watch;
    ftw; ftw64; nftw; nftw64; pathconf; getxattr; lgetxattr; listxattr; llistxattr;
    execve; execveat; execv; execvp; execvpe; execl; execlp; execle; posix_spawn; posix_spawnp;
    unlink; unlinkat; rmdir;
    getpwnam; getpwnam_r; getpwuid; getpwuid_r; getgrnam; getgrnam_r; getgrgid; getgrgid_r;
    sys_resolver_candidates;
  local: *;
};
